return {["market_ledger"]={["title"]="Anotacao do deposito",["pages"]={{["prefix"]="doc655_market_ledger_1",["title"]="Anotacao do deposito",["lines"]={"Catarina deixou a chave da Casa 12 comigo. Disse que","alguem levou o copo para a praca. As luzes apagaram","logo depois. Guardei a chave junto das caixas. A casa","fica na Rua dos Cedros."}}},["mother"]=false},["note"]={["title"]="Bilhete na cozinha",["pages"]={{["prefix"]="doc655_note_1",["title"]="Bilhete na cozinha",["lines"]={"A pizza ja foi pedida. Volto antes de esfriar. Deixei as","coisas em cima da mesa. Nao comecem sem mim."}}},["mother"]=false},["letter"]={["title"]="Carta antiga",["pages"]={{["prefix"]="doc655_letter_1",["title"]="Carta antiga",["lines"]={"Achei a carta de voces da faculdade. Nao acredito que","ainda guardam o copo. Se forem repetir aquela","brincadeira, me esperem. Quero ver se alguem tem","coragem."}}},["mother"]=false},["mother_note39"]={["title"]="Recado da mae",["pages"]={{["prefix"]="doc655_mother_note39_1",["title"]="Recado da mae",["lines"]={"Filha, seu irmao foi jogar bola e levou a chave. Ele","deve estar no campinho."}}},["mother"]=true},["gazebo_order"]={["title"]="Bilhete no coreto",["pages"]={{["prefix"]="doc655_gazebo_order_1",["title"]="Bilhete no coreto",["lines"]={"Nao espere na frente. A persiana do mercadinho travou","de novo. Use a porta de servico, no canto direito.","Deixei a chave do deposito perto do caixa. - N."}}},["mother"]=false},["order"]={["title"]="Pedido de entrega",["pages"]={{["prefix"]="doc655_order_1",["title"]="Pedido de entrega",["lines"]={"Pedido 37. Uma pizza grande. Entrega na casa 37.","Pagamento na entrega. O cliente pediu para insistir na","campainha."}},{["prefix"]="doc655_order_2",["title"]="Manual: movimento e interacao",["lines"]={"Direcional: movimentar.","Y: correr.","B: interagir, confirmar e recolher objetos.","A: abrir o inventario ou voltar.","Examine portas e pistas com B."}},{["prefix"]="doc655_order_3",["title"]="Manual: combate",["lines"]={"Segure R para preparar o ataque.","R + Y: soco ou ataque com a arma equipada.","R + X: chute.","A mira automatica pode ser ligada ou desligada nas","opcoes do menu."}},{["prefix"]="doc655_order_4",["title"]="Manual: inventario e arquivos",["lines"]={"A: abrir o inventario.","L / R: alternar Itens e Arquivos.","Direcional: escolher item ou arquivo.","B: confirmar, usar ou ler.","Arquivos nao ocupam os espacos dos itens."}},{["prefix"]="doc655_order_5",["title"]="Manual: leitura de documentos",["lines"]={"Com o bilhete na tela, B abre a transcricao.","Na leitura: esquerda / direita mudam a pagina.","B avanca ou retorna a lista na ultima pagina.","A volta para a lista de arquivos."}},{["prefix"]="doc655_order_6",["title"]="Teclado: previa do jogo",["lines"]={"WASD: movimentar. L: correr.","J: acao e confirmar. K: inventario ou voltar.","R + L: soco ou arma. R + M: chute.","M / R: alternar as abas do inventario.","A / D: mudar a pagina de leitura."}}},["mother"]=false}}
